src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    counts = Counter(v for row in grid for v in row)
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for color, count in counts.items():
        if color == bg or count < 10:
            continue
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen:
                    continue
                q = deque([(r,c)])
                seen.add((r,c))
                cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                            seen.add((yy,xx)); q.append((yy,xx))
                if len(cells) < 10:
                    continue
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                if len(cells) / ((r1-r0+1)*(c1-c0+1)) >= 0.65:
                    for y in range(r0,r1+1):
                        for x in range(c0,c1+1): out[y][x]=color
    return out
'''
